/bin/zsh -lc "python3 - <<'PY'
from pathlib import Path
import subprocess,os,signal,shutil,hashlib,json,time
work=Path('/Users/sam/.codex/worktrees/feat-qwen3-asr/ironmlx');backup=Path('/Volumes/Dev/ironmlx/.build/archives/feat-qwen3-asr-2026-11-02')
backup.mkdir(parents=True,exist_ok=False)
files=['docs/zh-CN/qwen3-asr-validation.md','docs/validation/qwen3-alignment-2026-10-17.json','docs/validation/qwen3-alignment-samples-2026-10-17.json','scripts/evaluate-qwen3-alignment.py']
def digest(p):
 h=hashlib.sha256()
 with p.open('rb') as f:
  for chunk in iter(lambda:f.read(1024*1024),b''):h.update(chunk)
 return h.hexdigest()
records={}
for name in files:
 target=backup/'uncommitted'/name;target.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(work/name,target)
 sha=digest(work/name);assert sha==digest(target);records[name]=sha
(backup/'uncommitted.patch').write_bytes(subprocess.check_output(['git','-C',str(work),'diff','--binary']))
for pid in [52205,52206]:
 try:row=subprocess.check_output(['ps','-p',str(pid),'-o','ppid=,args='],text=True).strip()
 except subprocess.CalledProcessError:continue
 parent,args=row.split(None,1)
 assert parent=='1' and str(work) in args and 'backend_crash_helper.py' in args,row
 os.kill(pid,signal.SIGTERM)
for name in ['ZIPFoundation','Sparkle']:
 checkout=work/'ironmlx-app/.build/checkouts'/name
 assert not subprocess.check_output(['git','-C',str(checkout),'status','--porcelain'],text=True).strip(),name
print('Four evaluation files backed up and verified; orphan test helpers stopped.',flush=True)
source=work/'.build';destination=backup/'build-evidence';shutil.copytree(source,destination,symlinks=True)
evidence={}
for p in source.rglob('*'):
 rel=p.relative_to(source);target=destination/rel
 if p.is_symlink():assert os.readlink(p)==os.readlink(target)
 elif p.is_file():
  sha=digest(p);assert sha==digest(target),str(rel);evidence[str(rel)]=sha
manifest={'original_worktree':str(work),'feature_tip':subprocess.check_output(['git','-C',str(work),'rev-parse','HEAD'],text=True).strip(),'evaluation_files_sha256':records,'build_evidence_sha256':evidence}
(backup/'backup-manifest.json').write_text(json.dumps(manifest,indent=2)+'\\n')
print('Build evidence copied and hash-verified:',len(evidence),'files.',flush=True)
assert source==work/'.build' and not source.is_symlink()
shutil.rmtree(source)
shutil.rmtree(work/'ironmlx-app/.build')
print('Verified backup:',backup,flush=True)
PY"
